SELECT OPTION_ID
FROM VOTES
WHERE POLL_ID = #{pollId}
  AND USER_ID = #{userId}
  AND ROWNUM = 1

SELECT COUNT(*)
FROM VOTES
WHERE POLL_ID = #{pollId}
  AND USER_ID = #{userId}

SELECT COUNT(*)
FROM VOTES
WHERE POLL_ID = #{pollId}

mapper.update:
UPDATE POLLS
SET QUESTION = #{question, jdbcType=VARCHAR},
    END_DT = TO_DATE(#{endDt, jdbcType=VARCHAR}, 'YYYY-MM-DD HH24:MI')
WHERE POLL_ID = #{pollId, jdbcType=NUMERIC}
  AND USER_ID = #{userId, jdbcType=NUMERIC}

UPDATE POLL_OPTIONS
SET TEXT = #{text, jdbcType=VARCHAR},
    OPTION_TYPE = #{optionType, jdbcType=VARCHAR},
    IMAGE_PATH = #{imagePath, jdbcType=VARCHAR}
WHERE OPTION_ID = #{optionId, jdbcType=NUMERIC}
  AND POLL_ID = #{pollId, jdbcType=NUMERIC}
